package ru.liturgyguide.service.book

import ru.liturgyguide.model.BookChapter
import ru.liturgyguide.model.ServiceBook
import java.text.Normalizer
import java.util.Locale

/** Editorial explanations, not quotations and not a claim about a parish's actual actions. */
object BookMeaningCatalog {
    val sourceUrls = listOf(
        "https://azbyka.ru/worships/o-proekte/",
        "https://azbyka.ru/stepenny",
        "https://www.oca.org/orthodoxy/the-orthodox-faith/worship/the-divine-liturgy/fervent-supplication",
        "https://www.oca.org/orthodoxy/the-orthodox-faith/worship/the-divine-liturgy/offertory-great-entrance",
        "https://www.oca.org/orthodoxy/the-orthodox-faith/worship/the-daily-cycles-of-prayer/matins",
        "https://www.oca.org/liturgics/outlines/the-division-of-the-psalter-into-kathismas",
        "https://www.oca.org/files/PDF/Music/Rubrics/Horologion/office-daily-matins.pdf",
        "https://www.russianorthodoxchurch.ws/synod/engdocuments/enart_ganirmos.html",
        "https://www.oca.org/orthodoxy/the-orthodox-faith/worship/the-divine-liturgy/antiphons",
        "https://www.oca.org/orthodoxy/the-orthodox-faith/worship/the-divine-liturgy/eucharistic-canon-anaphora",
        "https://www.oca.org/orthodoxy/the-orthodox-faith/worship/the-divine-liturgy/epiklesis"
    )

    /** Current app help, not a new accepted edition of the source text or its translation. */
    fun displayMeaning(book: ServiceBook, chapter: BookChapter): String =
        reviewedMeaning(chapter.title, chapter.blocks.joinToString(" ") { it.original },
            book.key.worship.queryValue, book.title) ?: chapter.meaning

    /** Unknown headings deliberately return null: a guessed explanation can misidentify a prayer. */
    fun meaningFor(title: String, original: String = "", worship: String = "liturgy"): String? {
        reviewedMeaning(title, original, worship)?.let { return it }
        val heading = normalize(title)
        val opening = normalize(original).take(400)
        fun titleHas(vararg values: String) = values.any { heading.contains(normalize(it)) }
        fun begins(vararg values: String) = values.any { opening.startsWith(normalize(it)) }
        return when {
            titleHas("Благодарственные молитвы", "Благодарственная молитва", "Благодарственная ектения") ->
                "После Причащения благодарят Бога за принятый дар и просят, чтобы эта встреча меняла повседневную жизнь. Молитва продолжается и после окончания общей службы"
            titleHas("Ектения об оглашенных", "Молитва об оглашенных") ->
                "Молятся о людях, которые готовятся к Крещению: чтобы они узнали веру и вошли в жизнь Церкви. Возглас \"Оглашенные, выйдите\" сохраняет древний порядок, когда некрещеные уходили перед Евхаристией. В современных приходах порядок участия может отличаться"
            titleHas("Литургия оглашенных") ->
                "Первая часть литургии готовит к слушанию слова Божия. Общие молитвы и песнопения ведут к чтениям Апостола и Евангелия; название связано с теми, кто готовился к Крещению"
            titleHas("Молитва верных", "Литургия верных") ->
                "Начинается часть литургии, посвященная Евхаристии и Причащению. Священник молится, чтобы собравшиеся могли с чистой совестью принести благодарение Богу и принять Его дары"
            titleHas("Заупокойная ектения") ->
                "Молятся об умерших: просят для них прощения грехов и покоя у Бога. Здесь можно мысленно вспомнить своих усопших близких"
            titleHas("Сугубая ектения", "Ектения сугубая") ->
                "Это усиленная общая молитва о людях и их нуждах. После прошений хор обычно трижды отвечает \"Господи, помилуй\"; в этой части могут добавлять местные прошения"
            titleHas("Великая ектения", "Ектения великая") ->
                "Диакон или священник произносит короткие просьбы о мире, Церкви, нашем городе, больных и путешествующих. Хор отвечает \"Господи, помилуй\" от лица молящихся"
            titleHas("Малая ектения") ->
                "Короткая общая молитва соединяет части службы. Слышно \"Паки и паки\" - то есть \"снова и снова\"; молящиеся вновь вверяют себя и друг друга Богу"
            titleHas("Просительная ектения", "Ектения просительная") ->
                "Просим у Бога мира, прощения и помощи прожить время службы и всю жизнь по совести. На многие просьбы хор отвечает \"Подай, Господи\""
            titleHas("Великий вход") ->
                "Священнослужители переносят приготовленные хлеб и вино на престол. Их освящение еще впереди, в евхаристической молитве; сейчас звучат поминовения живых и умерших"
            titleHas("Малый вход", "Вход с Евангелием") ->
                "Священнослужители выносят Евангелие и входят с ним в алтарь. Это торжественное приготовление к слушанию слова Христа; возглас \"Премудрость, прости\" призывает стоять внимательно"
            titleHas("Символ веры") ->
                "Церковь вместе исповедует свою веру в Отца, Сына и Святого Духа, воплощение и воскресение Христа, Крещение и будущую жизнь. Это общий ответ веры перед евхаристической молитвой"
            titleHas("Чтение Апостола") ->
                "Чтец произносит отрывок из Деяний или посланий апостолов. Эти слова обращены к жизни христианской общины; выбранный отрывок зависит от церковного дня и праздника"
            titleHas("Чтение Евангелия") ->
                "Диакон или священник читает о жизни, словах и делах Иисуса Христа. Возглас \"Вонмем\" означает \"будем внимательны\"; после чтения может прозвучать проповедь"
            titleHas("Прокимен") ->
                "Короткий стих из Писания, чаще из псалма, поется с повторением перед чтением. Он помогает настроиться на тему последующего библейского отрывка"
            titleHas("Аллилуиарий") ->
                "Перед Евангелием поют \"Аллилуия\" - \"хвалите Бога\" - и стихи псалма. Это радостное приготовление к слушанию слов Христа"
            titleHas("Трисвятое") ->
                "Молящиеся прославляют святость Бога и просят Его милости: \"Святый Боже, Святый Крепкий, Святый Бессмертный\". На некоторых праздниках вместо этой песни звучит другое установленное песнопение"
            titleHas("Песнь Господу Иисусу Христу", "Единородный Сыне") ->
                "Песнь кратко исповедует, что Сын Божий стал человеком, был распят и победил смерть ради нашего спасения. Это обращение к Христу между антифонами"
            titleHas("Молитва первого антифона") ->
                "Священник молится в алтаре о людях, собравшихся в этом храме, и просит щедрой милости Бога. Эта молитва может произноситься тихо, отдельно от слышимого пения антифона"
            titleHas("Молитва второго антифона") ->
                "Священник просит Бога сохранить Церковь, освятить тех, кто заботится о храме, и не оставить надеющихся на Него. Это молитва в алтаре; она может звучать тихо, пока хор поет"
            titleHas("Молитва третьего антифона") ->
                "Священник вспоминает обещание Христа услышать согласную молитву собравшихся во имя Его. Просит исполнить их прошения ко благу, даровать познание истины и вечную жизнь; молитва может произноситься тихо в алтаре"
            titleHas("Степенны", "Степенные антифоны") ->
                "Эти песнопения звучат на торжественной утрене перед чтением Евангелия. Они развивают образы псалмов восхождения - обращение к Богу, борьбу со злом и надежду на Его помощь - и завершаются прославлением Святого Духа"
            titleHas("Отче наш") ->
                "Молящиеся обращаются к Богу как к Отцу словами, которым научил Христос. Просят о хлебе насущном, прощении и избавлении от зла, связывая свою молитву с прощением другим людям"
            titleHas("Молитва перед св. Причащением", "Молитва перед Причащением") ->
                "Перед Причащением человек исповедует веру во Христа и просит прощения и исцеления. В центре молитвы - надежда на милость Бога, а не утверждение собственной безгрешности"
            titleHas("Причащение народа", "Причащение мирян") ->
                "Чашу выносят из алтаря, и подготовившиеся к Причащению подходят к ней. Звучит приглашение \"Со страхом Божиим и верою приступите\"; порядок подготовки и участия можно заранее уточнить у священника"
            titleHas("По причащении") ->
                "После Причащения община благодарит Бога и просит сохранить этот дар в своей жизни. Пение постепенно переходит к заключительным молитвам литургии"
            titleHas("Причастен", "Причастны") ->
                "Пока священнослужители причащаются в алтаре, хор поет причастный стих. Он берется из Писания и связан с днем или праздником; это время спокойной молитвы перед Причащением народа"
            titleHas("Заамвонная") ->
                "Священник выходит из алтаря и вслух произносит заключительную молитву. Просит Бога сохранить Церковь, благословить людей и даровать миру мир"
            titleHas("Отпуст") ->
                "Священник благословляет молящихся и просит Христа помиловать и спасти их по молитвам Богородицы и святых. Это завершение службы; ее молитву предстоит продолжить делами обычной жизни"
            titleHas("Многолетие") ->
                "Краткое пение с пожеланием многих лет жизни и Божией помощи. В нем могут поминать церковных предстоятелей, общину и других людей"
            titleHas("Шестопсалмие") ->
                "В начале утрени читают шесть псалмов о беде, покаянии, надежде и помощи Божией. В храме обычно слушают особенно тихо, без других действий и разговоров"
            titleHas("Светильничные молитвы") ->
                "В начале вечерни священник молится о защите от зла, мире и помощи Божией. Часть этих молитв может звучать тихо, одновременно с чтением псалма"
            titleHas("Утренние молитвы") ->
                "Священник благодарит Бога и просит света, прощения и помощи для людей. Эти молитвы относятся к чину утрени, даже когда утреню служат вечером вместе с другими службами"
            titleHas("Господи, воззвах") ->
                "Псалмы выражают обращение к Богу: \"Господи, к Тебе взываю\". К их стихам присоединяют песнопения дня; каждение напоминает образ молитвы, поднимающейся к Богу, как дым ладана"
            titleHas("Вечерняя песнь Сыну Божию", "Свете тихий") ->
                "На исходе дня Церковь благодарит Христа, называя Его тихим светом славы Отца. Песня соединяет вечерний свет с надеждой на жизнь, которую дает Бог"
            titleHas("Молитва при наступлении вечера", "Сподоби, Господи") ->
                "Просим провести вечер без греха и надеемся на милость Бога. Молитва завершает благодарение за день просьбой о защите и помощи"
            titleHas("Молитва главопреклонения") ->
                "После приглашения склонить головы священник просит для молящихся Божией защиты и благословения. Это жест доверия Богу, а не поклон человеку, который произносит молитву"
            titleHas("Молитва святаго Симеона", "Песнь Симеона", "Ныне отпущаеши") ->
                "Звучат слова праведного Симеона, который встретил Младенца Христа и увидел в Нем спасение для всех народов. На вечерне эта песнь выражает мир и доверие Богу в завершение дня"
            titleHas("Бог Господь") ->
                "В начале утрени поют о явлении Господа и приветствуют Его приход. После повторяющихся стихов звучат тропари - краткие песнопения дня или праздника"
            titleHas("Полиелей") ->
                "В праздничной утрене поют псалмы, прославляющие милость Бога. Служба становится особенно торжественной; дальнейшие песнопения и чтение раскрывают смысл праздника"
            titleHas("Песнь Пресвятыя Богородицы", "Честнейшую", "Величит душа") ->
                "Поют евангельскую песнь Богородицы о величии и милости Бога. Стихи обычно чередуются с припевом \"Честнейшую Херувим\", прославляющим Матерь Христа"
            titleHas("Славословие") ->
                "Молящиеся славят Бога и благодарят Его, просят прощения и помощи жить без греха. Славословие начинается ангельскими словами \"Слава в вышних Богу\""
            heading == "в алтаре" ->
                "Здесь приведены молитвы и действия священнослужителей в алтаре. Некоторые молитвы произносятся тихо, пока в храме читают или поют другой текст"
            titleHas("Начальные молитвы") || begins("Царю Небесный", "Благословен Бог наш") ->
                "Служба начинается с благословения и знакомых молитв. Они помогают собраться, попросить очищения и перейти от повседневных забот к общей молитве"
            begins("Благословено Царство") ->
                "Литургия открывается прославлением Царства Отца, Сына и Святого Духа. Ответ \"Аминь\" выражает согласие молящихся с этим началом общей молитвы"
            heading == "псалом 103" ->
                "Псалом прославляет Бога как Творца мира и Подателя жизни. В начале вечерни он помогает увидеть в смене дня и ночи, природе и человеческом труде заботу Божию"
            heading == "псалом 50" ->
                "Это покаянный псалом: человек признает свою вину и просит очищения, нового сердца и обновления духа. Надежда молитвы обращена к милости Бога"
            heading == "псалом 33" ->
                "Библейский псалом благодарит Бога за помощь и приглашает других разделить эту радость. Слова \"Вкусите и видите, яко благ Господь\" особенно созвучны благодарению после Причащения"
            titleHas("Псалом") ->
                "Здесь звучит библейский псалом - молитва, которая может выражать благодарность, боль, покаяние или надежду. Его слова помогают включить собственную жизнь в общую молитву"
            heading == "вечерня" ->
                "Вечерня завершает день благодарением и открывает новый богослужебный день. Псалмы, молитвы и песнопения готовят к предстоящему празднику или памяти святого"
            heading == "утреня" ->
                "Утреня соединяет псалмы, благодарение и песнопения дня. По приходскому обычаю ее могут служить вечером, поэтому название службы само по себе не указывает текущее время суток"
            titleHas("Первый час", "Третий час", "Шестой час", "Девятый час") ||
                (worship.startsWith("chas") && heading == "часы") ->
                "Часы - короткие службы с псалмами и молитвами, освящающие разные части дня. В храме их часто соединяют с другими службами, поэтому название часа не означает время на современных часах"
            else -> null
        }
    }

    /** Only this reviewed subset can update the app's help for an already accepted book. */
    private fun reviewedMeaning(title: String, original: String, worship: String, bookTitle: String = ""): String? {
        val heading = normalize(title)
        val text = normalize(original)
        val liturgy = worship == "liturgy" && !normalize(bookTitle).contains("преждеосвящ")
        fun starts(pattern: String) = Regex("^(?:$pattern)(?:\\b|$)").containsMatchIn(heading)
        // These prayers and Matins antiphons keep their own existing explanations.
        if (heading.startsWith("молитва ") || heading.startsWith("степенны") || heading.startsWith("степенные ")) return null
        val anaphora = heading in setOf("святое возношение", "анафора", "евхаристическая молитва",
            "евхаристический канон", "канон евхаристический")
        val figurativeAntiphon = heading in setOf("первый изобразительный антифон", "второй изобразительный антифон")
        val figurativePsalms = heading in setOf("изобразительны", "изобразительные псалмы") &&
            listOf("псалом 102", "псалом 145", "благослови душе моя господа", "хвали душе моя господа").any {
                text.replace(Regex("[,.!?;:]"), "").startsWith(it)
            }
        val beatitudesAlias = Regex("^блаженны, третий изобразительный антифон(?: \\(на (?:4|6|8|10|12)\\))?$").matches(heading) &&
            Regex("^во царствии твоем помяни нас господи(?:\\b|$)").containsMatchIn(
                text.replace(Regex("[,.!?;:/]"), " ").replace(Regex("\\s+"), " ").trim())
        return when {
            liturgy && anaphora ->
                "В этой молитве Церковь благодарит Бога, вспоминая Тайную вечерю, смерть и воскресение Христа, и просит Бога освятить Дары действием Святого Духа. По вере Церкви хлеб и вино становятся Телом и Кровью Христовыми. Слышны возгласы и ответы хора, в том числе \"Тебе поем\"; часть молитвы священник может читать тихо"
            liturgy && heading in setOf("херувимская", "херувимская песнь") &&
                listOf("ныне силы небесныя", "да молчит всякая плоть", "вечери твоея тайныя днесь").none(text::contains) ->
                "Хор поет \"Иже Херувимы...\" - приглашает вместе с ангелами прославить Бога и отложить повседневные заботы. Во время песни священнослужители переносят хлеб и вино на престол, священный стол в алтаре. Их освящение будет позже, в евхаристической молитве"
            liturgy && (figurativeAntiphon || figurativePsalms) ->
                "В псалмах \"Благослови, душе моя, Господа\" и \"Хвали, душе моя, Господа\" человек благодарит Бога за Его помощь. Эти песни в начале литургии готовят к общей молитве и слушанию Евангелия"
            liturgy && (heading == "блаженства" || beatitudesAlias) ->
                "Звучат заповеди Христа из Нагорной проповеди и просьба \"Во Царствии Твоем помяни нас, Господи\". Христос обещает Божие Царство и зовет к милосердию, чистоте сердца и миру с людьми"
            liturgy && Regex("^(?:(?:первый|второй|третий|1-й|2-й|3-й)\\s+)?(?:(?:вседневный|праздничный)\\s+)?антифон(?:ы|\\s+[1-3])?$").matches(heading) ->
                "Хор поет стихи псалмов с повторяющимся припевом. Эти песни в начале литургии прославляют Бога и готовят к входу с Евангелием. На праздниках слова и припев могут меняться"
            Regex("^кафизма(?:\\s+(?:[1-9]|1[0-9]|20))?$").matches(heading) ->
                "Кафизма - раздел Псалтири, книги библейских молитв. Здесь последовательно читают назначенную часть этой книги. Ее слова помогают обращаться к Богу с благодарностью, болью и надеждой"
            starts("канон") && !heading.contains("евхарист") ->
                "Канон - большой раздел службы из нескольких частей, которые называются песнями. Короткие песнопения читают или поют, обычно с повторяющимися молитвенными припевами. Библейские образы помогают рассказать о Христе, празднике или святом"
            Regex("^песнь [1-9](?:\\b|$)").containsMatchIn(heading) ->
                "Это одна из частей канона. Между короткими песнопениями обычно повторяется молитвенный припев: по нему легче понять, к кому обращена молитва. Библейские образы связывают эту часть с темой праздника или памятью святого"
            heading == "хвалитны" ->
                "Звучат хвалитные псалмы с призывом \"Хвалите Господа\". Небо, земля и всё живое призываются славить Творца. В зависимости от дня к псалмам добавляются стихиры - песнопения праздника или святых"
            starts("стихиры") ->
                "Стихиры - песнопения, которые обычно чередуются со стихами псалмов. Они раскрывают тему службы: прославляют Христа, Богородицу или святых, говорят о празднике и покаянии. Так слова псалмов соединяются с молитвой этого дня"
            starts("тропарь|тропари|кондак|кондаки") ->
                "Это краткие песнопения о празднике или святых. В них можно услышать, за что Церковь прославляет Бога и о чем просит Его. Обращение к святому часто содержит просьбу молиться о нас"
            starts("седален") ->
                "Короткое песнопение после псалмов или части канона возвращает внимание к теме службы: Христу, Богородице или святым дня. В его словах соединяются воспоминание о них и молитва"
            starts("светилен|светильны|cветильны|ексапостиларий") ->
                "Это короткое песнопение утрени, которое обычно звучит после канона. Оно говорит о Христе, Богородице или святых дня и подводит к хвалитным псалмам - общей хвале Богу"
            else -> null
        }
    }

    private fun normalize(value: String): String = Normalizer.normalize(
        // A breve distinguishes й from и. Removing every combining mark made real
        // headings such as "третий" fail the narrowly spelled reviewed rules.
        Normalizer.normalize(value, Normalizer.Form.NFD).replace(Regex("[\\p{M}&&[^\\u0306]]+"), ""),
        Normalizer.Form.NFC)
        .lowercase(Locale.ROOT).replace('ё', 'е').replace(Regex("\\s+"), " ").trim()
}
